export STATE_DIR=$(mktemp -d /tmp/bot-state.XXXXXX) && node --input-type=module -e '
import { execFileSync } from "node:child_process";
import * as bot from "./bot.mjs";
const ok = (c, m) => { if (!c) { console.log("FAIL", m); process.exitCode = 1; } else console.log("ok  ", m); };
const d = (s) => new Date(s);
const mk = (to, kind="marketing") => ({ to, kind });

// Unsubscribe, then marketing refused; transactional still allowed
await bot.recordUnsubscribe("<EMAIL>", d("2026-10-01T10:00:00Z"));
let r = await bot.mayEmail(mk("<EMAIL>"), d("2026-10-22T09:00:00Z"));
ok(r.allowed === false && r.reason === "unsubscribed", "marketing refused after unsubscribe (gmail dot/+tag variant): " + JSON.stringify(r));
r = await bot.mayEmail(mk("<EMAIL>", "transactional"), d("2026-10-22T09:00:00Z"));
ok(r.allowed === true && r.reason === null, "transactional receipt still allowed");

// Header form "Name <addr>" maps to same person
await bot.recordUnsubscribe("Jane <<EMAIL>>", d("2026-10-02T00:00:00Z"));
r = await bot.mayEmail(mk("Jane <<EMAIL>>"), d("2026-10-22T09:00:00Z"));
ok(r.reason === "unsubscribed", "header form + googlemail alias blocked");

// Out of order: resubscribe at T2 arrives first, older unsubscribe at T1 arrives later -> stays subscribed
await bot.recordResubscribe("bob@example.com", d("2026-10-10T00:00:00Z"));
await bot.recordUnsubscribe("bob@example.com", d("2026-10-05T00:00:00Z"));
r = await bot.mayEmail(mk("bob@example.com"), d("2026-10-22T00:00:00Z"));
ok(r.allowed === true, "late older unsubscribe does not undo newer resubscribe");

// Newer unsubscribe after resubscribe -> opted out
await bot.recordUnsubscribe("bob@example.com", d("2026-10-15T00:00:00Z"));
r = await bot.mayEmail(mk("bob@example.com"), d("2026-10-22T00:00:00Z"));
ok(r.reason === "unsubscribed", "newer unsubscribe wins over older resubscribe");

// Concurrent writes from many async callers are all kept
await Promise.all(Array.from({length: 30}, (_, i) => bot.recordUnsubscribe("carol@example.com", d(`2026-09-${String(1+(i%28)).padStart(2,"0")}T00:00:00Z`))));
await bot.recordResubscribe("carol@example.com", d("2026-09-01T00:00:00Z"));
r = await bot.mayEmail(mk("carol@example.com"), d("2026-10-22T00:00:00Z"));
ok(r.reason === "unsubscribed", "carol opted out (unsub Sep 28 > resub Sep 1) after 30 concurrent writes");

// Another process (simulated worker restart) sees the same state
const out = execFileSync(process.execPath, ["--input-type=module", "-e",
  "import * as b from \"./bot.mjs\"; const r = await b.mayEmail({to:\"<EMAIL>\",kind:\"marketing\"}, new Date()); console.log(JSON.stringify(r));"],
  { env: process.env, encoding: "utf8" });
ok(out.includes("unsubscribed"), "child process sees unsubscribe: " + out.trim());

// Unknown kind / bad address / bad time are refused, not thrown
ok((await bot.mayEmail(mk("x@example.com","newsletter"), new Date())).reason === "unknown_kind", "unknown kind refused");
ok((await bot.mayEmail(mk("not-an-email"), new Date())).reason === "invalid_recipient", "invalid recipient refused");
ok((await bot.mayEmail(mk("new@example.com"), new Date("nope"))).reason === "invalid_time", "invalid now refused");

// Never-seen marketing address is allowed (no state)
r = await bot.mayEmail(mk("fresh@example.com"), new Date());
ok(r.allowed === true && r.reason === null, "fresh marketing address allowed");

// Bad input to record throws
let threw = false; try { await bot.recordUnsubscribe("nope", new Date()); } catch { threw = true; }
ok(threw, "recordUnsubscribe rejects non-address");
' ; echo "exit=$?"; rm -rf "$STATE_DIR"
